<?php else: ?><section class="staff-panel"><h2>Pelaku terpilih</h2><p><strong><?= html_escape($person['full_name']) ?></strong> · ID #<?= (int)$person_id ?>. <a href="<?= site_url('pengelola/pelaku/'.$person_id) ?>">Periksa profil pelaku</a></p><form method="post" action="<?= site_url('pengelola/registri/baru').'?person_id='.(int)$person_id ?>" class="master-form">
