<label>Desa atau kelurahan<select class="form-select" name="village_id"><option value="">Belum dipilih</option><?php foreach($villages as $village): ?><option value="<?= (int)$village['id'] ?>" data-district="<?= (int)$village['district_id'] ?>" <?= (int)$this->input->post('village_id',TRUE)===(int)$village['id']?'selected':'' ?>><?= html_escape($village['name']) ?></option><?php endforeach; ?></select></label>
<label>Skala usaha<select class="form-select" name="scale_id"><option value="">Belum ditentukan</option><?php foreach($scales as $scale): ?><option value="<?= (int)$scale['id'] ?>" <?= (int)$this->input->post('scale_id',TRUE)===(int)$scale['id']?'selected':'' ?>><?= html_escape($scale['name']) ?></option><?php endforeach; ?></select></label>
