<label>Telepon kegiatan<input class="form-control" type="tel" name="contact_phone" maxlength="20" value="<?= html_escape((string)$this->input->post('contact_phone',TRUE)) ?>"></label>
<label>Sumber atau dasar pencatatan<textarea class="form-control" name="source_note" required minlength="20" maxlength="500" rows="3" placeholder="Catat sumber informasi tanpa menyalin NIK lengkap."><?= html_escape((string)$this->input->post('source_note',TRUE)) ?></textarea></label>
<button class="btn btn-primary" type="submit">Simpan kegiatan untuk pelaku ini</button></form></section><?php endif; ?>
<script>document.addEventListener('DOMContentLoaded',function(){const d=document.querySelector('[name=district_id]'),v=document.querySelector('[name=village_id]');if(!d||!v)return;function sync(){Array.from(v.options).forEach(function(o){if(o.value)o.hidden=o.dataset.district!==d.value});if(v.selectedOptions[0]&&v.selectedOptions[0].hidden)v.value=''}d.addEventListener('change',sync);sync()})</script>
